.pm-chapter-section { --ink: #2d3748; --muted: #718096; --accent: #2C5282; --warm: #DD6B20; --line: #e2e8f0; --paper: #f7fafc; font-family: system-ui, -apple-system, sans-serif; color: var(--ink); background: var(--paper); padding: 24px; line-height: 1.6; font-size: 16px; box-sizing: border-box; }
.pm-chapter-section * { box-sizing: border-box; }
.pm-section-header { margin-bottom: 24px; border-bottom: 2px solid var(--accent); padding-bottom: 12px; }
.pm-section-title { font-size: 24px; font-weight: 700; margin: 0 0 8px 0; color: var(--accent); }
.pm-section-summary { font-size: 16px; color: var(--muted); margin: 0; }
.pm-content-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; margin-bottom: 32px; }
@media (max-width: 768px) { .pm-content-grid { grid-template-columns: 1fr; } }
.pm-paragraph { font-size: 16px; margin-bottom: 16px; text-align: justify; }
.pm-source-btn { display: inline-block; background: #edf2f7; border: 1px solid var(--line); color: var(--accent); padding: 4px 8px; font-size: 13px; border-radius: 4px; cursor: pointer; margin-left: 8px; vertical-align: middle; }
.pm-source-btn:hover { background: #e2e8f0; }
.pm-formula-box { background: #fff; border: 1px solid var(--line); padding: 16px; margin: 16px 0; border-radius: 6px; }
.pm-formula { font-family: 'Times New Roman', serif; font-size: 18px; text-align: center; margin: 8px 0; color: var(--ink); }
.pm-formula-note { font-size: 14px; color: var(--muted); text-align: center; margin-top: 8px; }
.pm-visual-workbench { background: #fff; border: 1px solid var(--line); border-radius: 8px; padding: 16px; }
.pm-viz-title { font-size: 18px; font-weight: 600; margin: 0 0 8px 0; color: var(--accent); }
.pm-viz-caption { font-size: 13px; color: var(--muted); margin-bottom: 16px; }
.pm-controls { display: flex; flex-direction: column; gap: 12px; margin-bottom: 16px; }
.pm-control-group { display: flex; align-items: center; gap: 8px; }
.pm-control-group label { font-size: 14px; font-weight: 500; min-width: 140px; }
.pm-control-group input[type="range"] { flex: 1; }
.pm-control-group span { font-size: 14px; font-family: monospace; min-width: 30px; text-align: right; }
.pm-canvas-wrapper { display: flex; flex-direction: column; gap: 8px; margin-bottom: 16px; }
canvas { width: 100%; height: auto; background: #fff; border: 1px solid var(--line); border-radius: 4px; }
.pm-data-display { display: flex; align-items: center; gap: 8px; font-size: 14px; }
.pm-label { font-weight: 500; }
#pe-value { font-family: monospace; font-weight: 700; color: var(--accent); }
.pm-limitations-section { background: #fff; border: 1px solid var(--line); padding: 16px; border-radius: 8px; }
.pm-sub-title { font-size: 18px; font-weight: 600; margin: 0 0 12px 0; color: var(--ink); }
.pm-list { margin: 0; padding-left: 20px; }
.pm-list li { font-size: 15px; margin-bottom: 8px; color: var(--ink); }
.pe-axis-note{font-size:13px;line-height:1.8;color:var(--muted)}.pm-content-grid{grid-template-columns:minmax(0,1fr)}.pm-visual-workbench{max-width:100%}.pm-visual-workbench canvas{max-height:260px}.pm-control-group{flex-wrap:wrap}.pm-control-group label{min-width:0;flex-basis:180px}

section[id]{--ink:#233342;--muted:#596877;--accent:#265976;--warm:#ad472d;--line:#d6dcd9;--paper:#fcfbf8;background:transparent;border:0;border-radius:0;padding:0;max-width:100%;color:var(--ink)}
section[id] h2{color:#233342;font-family:Georgia,"Noto Serif SC",SimSun,serif;font-weight:500;font-size:29px;line-height:1.5}
section[id]>header{border-bottom:1px solid #d6dcd9}section[id] p{line-height:1.9}
section[id] [class*="formula"]{max-width:100%;overflow-x:auto}
section[id] [class*="panel"],section[id] [class*="workbench"]{box-shadow:none}
@media(max-width:600px){section[id] div{min-width:0;max-width:100%}section[id] h2{font-size:25px}section[id] [class*="grid"]{grid-template-columns:minmax(0,1fr)}section[id] .pm-matrix-grid{grid-template-columns:repeat(3,minmax(0,1fr))}section[id] .pm-input-row input{min-width:0;flex:1;width:0}section[id] .pm-control-group{flex-wrap:wrap}section[id] .pm-control-group label{min-width:0;flex-basis:100%}section[id] .pm-section-header{flex-wrap:wrap}section[id] .pm-lab-panel,section[id] .interaction-panel{padding:14px}section[id] .pm-head-visual{display:block}section[id] .pm-control-group span{min-width:0}}

javascript:
(function() {
  'use strict';
  const d_model = 64; // 教学示例维度
  const maxPos = 100;
  const maxDim = 64;

  const posInput = document.getElementById('pe-pos');
  const dimInput = document.getElementById('pe-dim');
  const posVal = document.getElementById('pe-pos-val');
  const dimVal = document.getElementById('pe-dim-val');
  const peValueEl = document.getElementById('pe-value');
  const interfaceData = document.getElementById('pe-interface-data');
  const heatmapCanvas = document.getElementById('pe-canvas');
  const waveformCanvas = document.getElementById('pe-waveform-canvas');

  const ctxHeat = heatmapCanvas.getContext('2d');
  const ctxWave = waveformCanvas.getContext('2d');

  // 计算 PE 值
  function calculatePE(pos, dim) {
    const i = Math.floor(dim / 2);
    const exponent = 2 * i / d_model;
    const divisor = Math.pow(10000, exponent);
    const angle = pos / divisor;
    if (dim % 2 === 0) {
      return Math.sin(angle);
    } else {
      return Math.cos(angle);
    }
  }

  // 绘制热力图
  function drawHeatmap() {
    const w = heatmapCanvas.width;
    const h = heatmapCanvas.height;
    const cellW = w / maxPos;
    const cellH = h / maxDim;

    for (let pos = 0; pos < maxPos; pos++) {
      for (let dim = 0; dim < maxDim; dim++) {
        const val = calculatePE(pos, dim);
        // 映射 -1..1 到 颜色
        const t=Math.abs(val); const from=[247,246,240],to=val>=0?[38,89,118]:[173,71,45];ctxHeat.fillStyle=`rgb(${from.map((v,i)=>Math.round(v+(to[i]-v)*t)).join(",")})`;
        ctxHeat.fillRect(pos * cellW, dim * cellH, cellW + 1, cellH + 1);
      }
    }

    // 绘制选中框
    const selPos = parseInt(posInput.value);
    const selDim = parseInt(dimInput.value);
    ctxHeat.strokeStyle = '#DD6B20';
    ctxHeat.lineWidth = 2;
    ctxHeat.strokeRect(selPos * cellW, selDim * cellH, cellW, cellH);
  }

  // 绘制波形图
  function drawWaveform() {
    const w = waveformCanvas.width;
    const h = waveformCanvas.height;
    const selDim = parseInt(dimInput.value);

    ctxWave.clearRect(0, 0, w, h);
    ctxWave.beginPath();
    ctxWave.strokeStyle = '#2C5282';
    ctxWave.lineWidth = 2;

    for (let pos = 0; pos < maxPos; pos++) {
      const val = calculatePE(pos, selDim);
      const x = (pos / maxPos) * w;
      const y = (h / 2) - (val * h / 2);
      if (pos === 0) ctxWave.moveTo(x, y);
      else ctxWave.lineTo(x, y);
    }
    ctxWave.stroke();

    // 绘制当前 pos 线
    const selPos = parseInt(posInput.value);
    const xPos = (selPos / maxPos) * w;
    ctxWave.strokeStyle = '#DD6B20';
    ctxWave.lineWidth = 1;
    ctxWave.setLineDash([4, 4]);
    ctxWave.beginPath();
    ctxWave.moveTo(xPos, 0);
    ctxWave.lineTo(xPos, h);
    ctxWave.stroke();
    ctxWave.setLineDash([]);
  }

  // 更新显示
  function updateDisplay() {
    const pos = parseInt(posInput.value);
    const dim = parseInt(dimInput.value);
    const val = calculatePE(pos, dim);

    posVal.textContent = pos;
    dimVal.textContent = dim;
    peValueEl.textContent = val.toFixed(4);
    peValueEl.setAttribute('data-value', val);

    // 同步接口数据
    interfaceData.setAttribute('data-values', JSON.stringify([pos, dim, val]));

    drawHeatmap();
    drawWaveform();
  }

  // 事件监听
  posInput.addEventListener('input', updateDisplay);
  dimInput.addEventListener('input', updateDisplay);

  // Canvas 点击交互
  heatmapCanvas.addEventListener('click', function(e) {
    const rect = heatmapCanvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) * heatmapCanvas.width / rect.width;
    const y = (e.clientY - rect.top) * heatmapCanvas.height / rect.height;
    const cellW = heatmapCanvas.width / maxPos;
    const cellH = heatmapCanvas.height / maxDim;

    const newPost = Math.min(maxPos - 1, Math.floor(x / cellW));
    const newDim = Math.min(maxDim - 1, Math.floor(y / cellH));

    posInput.value = newPost;
    dimInput.value = newDim;
    updateDisplay();
  });

  // 初始化
  updateDisplay();

  // 来源按钮处理 (由宿主内核接管)
  const sourceBtns = document.querySelectorAll('.pm-source-btn');
  sourceBtns.forEach(btn => {
    btn.addEventListener('click', function() {
      // 宿主内核会读取 data-source 属性
    });
  });
})();
